import{_ as e,o,c as a,a2 as n}from"./chunks/framework.BZO4qERu.js";const g=JSON.parse('{"title":"Коннекторы (Connect-It)","description":"","frontmatter":{},"headers":[],"relativePath":"ru/self-hosted/connectors.md","filePath":"ru/self-hosted/connectors.md","lastUpdated":1792323081000}'),s={name:"ru/self-hosted/connectors.md"};function r(i,t,h,d,l,c){return o(),a("div",null,[...t[0]||(t[0]=[n(`<h1 id="коннекторы-connect-it" tabindex="-1">Коннекторы (Connect-It) <a class="header-anchor" href="#коннекторы-connect-it" aria-label="Permalink to &quot;Коннекторы (Connect-It)&quot;">​</a></h1><p>Коннекторы позволяют Bot использовать инструменты сторонних сервисов, таких как GitHub и Notion. За ними стоит <a href="https://github.com/memohai/connect-it" target="_blank" rel="noreferrer">Connect-It</a> — сопутствующий сервис, развёртываемый рядом с Memoh. Все учётные данные (токены OAuth, ключи API) живут на стороне Connect-It; Memoh хранит только таблицу привязок: какой Bot привязан к какому подключению, как называется пространство имён инструментов и включено ли оно.</p><p>С точки зрения пользователя коннекторы не устанавливаются сами по себе: они приходят как компоненты <a href="./../guides/supermarket.html">приложения</a>. Манифест приложения объявляет, какие типы коннекторов оно использует и какие из них обязательны; после установки вы авторизуете их на вкладке <strong>Apps</strong> нужного Bot. Остальная часть этой страницы — взгляд оператора: как запустить Connect-It и как подключения устроены изнутри.</p><hr><h2 id="требования-к-серверу" tabindex="-1">Требования к серверу <a class="header-anchor" href="#требования-к-серверу" aria-label="Permalink to &quot;Требования к серверу&quot;">​</a></h2><p>Функция коннекторов появляется, только когда на сервере настроен эндпоинт Connect-It:</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">connect_it</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">base_url = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # например, &quot;http://connect-it:8421&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">api_token = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # доверенный межсерверный токен</span></span></code></pre></div><p>Если оставить оба значения пустыми, функция отключена. В продакшене предпочтительнее соответствующие переменные окружения (<code>MEMOH_CONNECT_IT_BASE_URL</code>, <code>MEMOH_CONNECT_IT_API_TOKEN</code>).</p><p>Server Deploy в одну команду при чистой установке поднимает совместно размещённый Connect-It; см. <a href="./docker.html#коннекторы-connect-it">Server Deploy</a>. Без настроенного Connect-It компоненты приложений, зависящие от коннектора, отображаются как недоступные.</p><hr><h2 id="авторизация-и-управление" tabindex="-1">Авторизация и управление <a class="header-anchor" href="#авторизация-и-управление" aria-label="Permalink to &quot;Авторизация и управление&quot;">​</a></h2><p>После установки приложения с коннекторами вкладка <strong>Apps</strong> у Bot показывает их среди компонентов приложения с пометками <strong>Needs authorization</strong>, <strong>Optional</strong> или <strong>Shared across workspaces</strong>. Нажмите <strong>Authorize</strong>, чтобы завершить привязку: OAuth проходит через всплывающее окно (если браузер его блокирует, разрешите всплывающие окна для страницы), а коннекторы с ключом API вместо этого запрашивают поля учётных данных.</p><p>У каждого подключения отображается статус:</p><table tabindex="0"><thead><tr><th>Статус</th><th>Значение</th></tr></thead><tbody><tr><td><strong>Connected</strong></td><td>Всё в порядке; инструменты доступны Bot</td></tr><tr><td><strong>Waiting for authorization</strong></td><td>Подключение создано, но OAuth так и не завершился; завершите его или отключите подключение</td></tr><tr><td><strong>Authorization required</strong></td><td>Учётные данные истекли или были отозваны; нажмите <strong>Reauthorize</strong></td></tr><tr><td><strong>Authorization failed</strong></td><td>Последняя попытка авторизации не удалась; <strong>Reauthorize</strong> повторяет её</td></tr><tr><td><strong>Unavailable</strong></td><td>Настроенный Connect-It не предоставляет этот тип коннектора</td></tr><tr><td><strong>Disabled</strong></td><td>Выключено; инструменты Bot не передаются</td></tr></tbody></table><p>Подключение можно <strong>включать и выключать</strong>, не удаляя его. <strong>Disconnect</strong> убирает привязку у Bot <strong>и</strong> удаляет сохранённое подключение (вместе с учётными данными) на стороне Connect-It — приложения, которые им пользовались, придётся авторизовать заново.</p><hr><h2 id="как-инструменты-попадают-к-bot" tabindex="-1">Как инструменты попадают к Bot <a class="header-anchor" href="#как-инструменты-попадают-к-bot" aria-label="Permalink to &quot;Как инструменты попадают к Bot&quot;">​</a></h2><p>Во время беседы Memoh объединяет все включённые и исправные подключения Bot в одну MCP-сессию и передаёт её агенту как источник инструментов. Инструменты коннекторов появляются рядом с инструментами рабочего пространства и MCP.</p><p>Каждое подключение в момент привязки получает <strong>пространство имён инструментов</strong>, сгенерированное из типа коннектора: подключение GitHub — <code>github</code>, второе такое же — <code>github-2</code>. Пространство имён остаётся неизменным на весь срок жизни привязки: добавление или удаление других подключений позже никогда не меняет имена инструментов уже существующих.</p><hr><h2 id="связанные-страницы" tabindex="-1">Связанные страницы <a class="header-anchor" href="#связанные-страницы" aria-label="Permalink to &quot;Связанные страницы&quot;">​</a></h2><ul><li><a href="./../guides/supermarket.html">Supermarket</a> — откуда устанавливаются приложения (включая компоненты-коннекторы).</li><li><a href="./../guides/mcp.html">MCP</a> — управление MCP-подключениями напрямую.</li><li><a href="./docker.html#коннекторы-connect-it">Server Deploy</a> — совместное размещение Connect-It, управление учётными данными и URL OAuth-колбэков.</li></ul>`,22)])])}const u=e(s,[["render",r]]);export{g as __pageData,u as default};
